function() {
  try {
    // 1. Check DataLayer first (Cal.com / Webhook event)
    var dlvName = {{dlv - cal name}} || {{dlv - name}};
    if (dlvName && typeof dlvName === "string") {
      var clean = dlvName.replace(/[^a-zA-Z\u00C0-\u00FF ]/g, "").trim();
      var fn = clean.split(/\s+/)[0];
      if (fn) return fn.charAt(0).toUpperCase() + fn.slice(1).toLowerCase();
    }
    var dlvFn = {{dlv - cal first_name}} || {{dlv - first_name}};
    if (dlvFn && typeof dlvFn === "string") {
      return dlvFn.trim().charAt(0).toUpperCase() + dlvFn.trim().slice(1).toLowerCase();
    }
  } catch(e){}

  // 2. Fallback to DOM input fields
  var inputs = document.querySelectorAll('input[placeholder*="Nome"], input[name*="name"], input[name*="nome"], input[autocomplete="name"]');
  for (var i = 0; i < inputs.length; i++) {
    if (inputs[i].value) {
      var cleanStr = inputs[i].value.replace(/[^a-zA-Z\u00C0-\u00FF ]/g, "").trim();
      var firstName = cleanStr.split(/\s+/)[0];
      if (firstName) return firstName.charAt(0).toUpperCase() + firstName.slice(1).toLowerCase();
    }
  }
  return undefined;
}

function() {
  try {
    // 1. Check DataLayer first
    var dlvName = {{dlv - cal name}} || {{dlv - name}};
    if (dlvName && typeof dlvName === "string") {
      var clean = dlvName.replace(/[^a-zA-Z\u00C0-\u00FF ]/g, "").trim();
      var parts = clean.split(/\s+/);
      if (parts.length > 1) {
        return parts.slice(1).join(" ").replace(/\w\S*/g, function(t){
          return t.charAt(0).toUpperCase() + t.substr(1).toLowerCase();
        });
      }
    }
    var dlvLn = {{dlv - cal last_name}} || {{dlv - last_name}};
    if (dlvLn && typeof dlvLn === "string") {
      return dlvLn.trim().replace(/\w\S*/g, function(t){
        return t.charAt(0).toUpperCase() + t.substr(1).toLowerCase();
      });
    }
  } catch(e){}

  // 2. Fallback to DOM
  var inputs = document.querySelectorAll('input[placeholder*="Nome"], input[name*="name"], input[name*="nome"]');
  for (var i = 0; i < inputs.length; i++) {
    if (inputs[i].value) {
      var cleanStr = inputs[i].value.replace(/[^a-zA-Z\u00C0-\u00FF ]/g, "").trim();
      var firstSpace = cleanStr.indexOf(" ");
      if (firstSpace !== -1) {
        var lastName = cleanStr.substring(firstSpace + 1).trim();
        return lastName.replace(/\w\S*/g, function(t){
          return t.charAt(0).toUpperCase() + t.substr(1).toLowerCase();
        });
      }
    }
  }
  return "";
}

function() {
  try {
    // 1. Check DataLayer first
    var dlvEmail = {{dlv - cal email}} || {{dlv - email}};
    if (dlvEmail && typeof dlvEmail === "string" && dlvEmail.indexOf("@") !== -1) {
      return dlvEmail.trim().toLowerCase();
    }
  } catch(e){}

  // 2. Fallback to DOM
  var inputs = document.querySelectorAll('input[type="email"], input[name*="email"]');
  for (var i = 0; i < inputs.length; i++) {
    if (inputs[i].value && inputs[i].value.indexOf("@") !== -1) {
      return inputs[i].value.trim().toLowerCase();
    }
  }
  return "";
}

function() {
  try {
    // 1. Check DataLayer first
    var dlvPhone = {{dlv - cal phone}} || {{dlv - phone}} || {{dlv - cal phoneNumber}};
    if (dlvPhone) {
      var nums = String(dlvPhone).replace(/[^0-9]/g, "");
      if (nums.length >= 8) {
        return nums.startsWith("55") || nums.startsWith("1") ? nums : "55" + nums;
      }
    }
  } catch(e){}

  // 2. Fallback to DOM
  var inputs = document.querySelectorAll('input[type="tel"], input[name*="phone"], input[name*="tel"]');
  for (var i = 0; i < inputs.length; i++) {
    if (inputs[i].value) {
      var cleaned = inputs[i].value.replace(/[^0-9]/g, "");
      return cleaned.startsWith("55") || cleaned.startsWith("1") ? cleaned : "55" + cleaned;
    }
  }
  return "";
}

